def count_stack_exterminable_subarrays(n, arr):
    stack = []
    next_indices = [n] * n
    for i in range(n - 1, -1, -1):
        while stack and arr[stack[-1]] >= arr[i]:
            next_indices[stack.pop()] = i
        stack.append(i)

    stack = []
    count = 0
    for i in range(n):
        while stack and arr[stack[-1]] >= arr[i]:
            top_index = stack.pop()
            count += (top_index - i) * (next_indices[top_index] - i)
        stack.append(i)

    return count

